using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capability using the DuckDuckGo Instant Answer API.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<WebSearchTool> _logger;

    public WebSearchTool(HttpClient httpClient, ILogger<WebSearchTool> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    [Description("Searches the web for information on a given query and returns relevant results. " +
                 "Use this tool to find facts, articles, and information about any topic.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        CancellationToken cancellationToken = default)
    {
        _logger.LogInformation("Searching the web for: {Query}", query);

        try
        {
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var response = await _httpClient.GetFromJsonAsync<DuckDuckGoResponse>(
                url, DuckDuckGoJsonContext.Default.DuckDuckGoResponse, cancellationToken);

            if (response is null)
            {
                return "No results found for the query.";
            }

            var results = new List<string>();

            if (!string.IsNullOrWhiteSpace(response.Abstract))
            {
                results.Add($"## Summary\n{response.Abstract}\nSource: {response.AbstractSource} ({response.AbstractUrl})");
            }

            if (!string.IsNullOrWhiteSpace(response.Answer))
            {
                results.Add($"## Direct Answer\n{response.Answer}");
            }

            foreach (var topic in response.RelatedTopics?.Take(5) ?? [])
            {
                if (!string.IsNullOrWhiteSpace(topic.Text))
                {
                    results.Add($"- {topic.Text} ({topic.FirstUrl})");
                }
            }

            if (results.Count == 0)
            {
                return $"No detailed results found for '{query}'. Try rephrasing the query or breaking it into simpler terms.";
            }

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Web search failed for query: {Query}", query);
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

public sealed class DuckDuckGoResponse
{
    [JsonPropertyName("Abstract")]
    public string? Abstract { get; set; }

    [JsonPropertyName("AbstractSource")]
    public string? AbstractSource { get; set; }

    [JsonPropertyName("AbstractURL")]
    public string? AbstractUrl { get; set; }

    [JsonPropertyName("Answer")]
    public string? Answer { get; set; }

    [JsonPropertyName("RelatedTopics")]
    public List<RelatedTopic>? RelatedTopics { get; set; }
}

public sealed class RelatedTopic
{
    [JsonPropertyName("Text")]
    public string? Text { get; set; }

    [JsonPropertyName("FirstURL")]
    public string? FirstUrl { get; set; }
}

[JsonSerializable(typeof(DuckDuckGoResponse))]
internal sealed partial class DuckDuckGoJsonContext : JsonSerializerContext;

using System.ComponentModel;
using System.Text;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capability for the research agent to collect and organize findings.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];
    private readonly ILogger<NoteTakingTool> _logger;

    public NoteTakingTool(ILogger<NoteTakingTool> logger)
    {
        _logger = logger;
    }

    [Description("Saves a research note with a title and content. " +
                 "Use this to record important findings, facts, and insights discovered during research.")]
    public string AddNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The detailed content of the note including facts, data, or insights")] string content,
        [Description("The source URL or reference where this information was found")] string source = "")
    {
        var note = new Note(title, content, source, DateTime.UtcNow);
        _notes.Add(note);
        _logger.LogInformation("Note added: {Title} (total: {Count})", title, _notes.Count);
        return $"Note '{title}' saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes. " +
                 "Use this to review what has been collected so far before writing a summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet. Use the AddNote tool to save research findings.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"## Research Notes ({_notes.Count} total)\n");

        for (int i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"### {i + 1}. {note.Title}");
            sb.AppendLine(note.Content);
            if (!string.IsNullOrWhiteSpace(note.Source))
            {
                sb.AppendLine($"*Source: {note.Source}*");
            }
            sb.AppendLine();
        }

        return sb.ToString();
    }

    private sealed record Note(string Title, string Content, string Source, DateTime Timestamp);
}

