using System.ComponentModel;
using System.Text;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capability for the research agent to collect and organize findings.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];
    private readonly ILogger<NoteTakingTool> _logger;

    public NoteTakingTool(ILogger<NoteTakingTool> logger)
    {
        _logger = logger;
    }

    [Description("Saves a research note with a title and content. " +
                 "Use this to record important findings, facts, and insights discovered during research.")]
    public string AddNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The detailed content of the note including facts, data, or insights")] string content,
        [Description("The source URL or reference where this information was found")] string source = "")
    {
        var note = new Note(title, content, source, DateTime.UtcNow);
        _notes.Add(note);
        _logger.LogInformation("Note added: {Title} (total: {Count})", title, _notes.Count);
        return $"Note '{title}' saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes. " +
                 "Use this to review what has been collected so far before writing a summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet. Use the AddNote tool to save research findings.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"## Research Notes ({_notes.Count} total)\n");

        for (int i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"### {i + 1}. {note.Title}");
            sb.AppendLine(note.Content);
            if (!string.IsNullOrWhiteSpace(note.Source))
            {
                sb.AppendLine($"*Source: {note.Source}*");
            }
            sb.AppendLine();
        }

        return sb.ToString();
    }

    private sealed record Note(string Title, string Content, string Source, DateTime Timestamp);
}

