using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient<WebSearchTool>(client =>
{
    client.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");
    client.Timeout = TimeSpan.FromSeconds(15);
});

builder.Services.AddSingleton<NoteTakingTool>();

builder.Services.AddChatClient(chatClientBuilder =>
    chatClientBuilder
        .UseLogging()
        .UseOpenAIChatClient(
            builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18",
            new OpenAIClient(
                builder.Configuration["AI:ApiKey"]
                    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
                    ?? throw new InvalidOperationException(
                        "Set the AI:ApiKey configuration value or the OPENAI_API_KEY environment variable."))));

builder.Logging.SetMinimumLevel(LogLevel.Warning);

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var searchTool = host.Services.GetRequiredService<WebSearchTool>();
var noteTool = host.Services.GetRequiredService<NoteTakingTool>();

var tools = new AITool[]
{
    AIFunctionFactory.Create(searchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTool.AddNote),
    AIFunctionFactory.Create(noteTool.GetAllNotes),
};

var innerAgent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI research assistant that searches the web and takes notes to produce a summary.",
        Instructions = """
            You are a thorough research assistant. When given a topic:

            1. Use the SearchWeb tool multiple times with different queries to gather diverse information.
            2. Use the AddNote tool to save each important finding with a clear title and source.
            3. After gathering enough information (at least 3-5 searches), use GetAllNotes to review your findings.
            4. Produce a well-structured summary with key facts, different perspectives, and source references.

            Be methodical: search broadly first, then drill into specific aspects of the topic.
            Always cite your sources in the final summary.
            """,
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    });

var agent = new LoopAgent(
    innerAgent,
    new CompletionMarkerLoopEvaluator(),
    new LoopAgentOptions { MaxIterations = 15 });

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║     AI Research Agent (MAF + MEAI)   ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research.          ║");
Console.WriteLine("║  Type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Research topic> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
    {
        continue;
    }

    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    Console.WriteLine($"\nResearching: {topic}");
    Console.WriteLine(new string('─', 50));

    try
    {
        await foreach (var update in agent.RunStreamingAsync(
            [new ChatMessage(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")]))
        {
            if (update.Text is { Length: > 0 } text)
            {
                Console.Write(text);
            }
        }

        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\nError: {ex.Message}");
    }

    Console.WriteLine(new string('─', 50));
    Console.WriteLine();
}

